sysauto_script.script:
(function() {
    var listGR = new GlideRecord("u_cisco_secure_access_destination_list");
    listGR.query();

    while (listGR.next()) {
        var count = parseInt(listGR.getValue("u_count") || "0", 10);
        var listName = listGR.getDisplayValue("u_list_name");

        if (count >= 5000) {
            var evt = new GlideRecord("em_event");
            evt.initialize();
            evt.source = "Cisco Integration";
            evt.node = listName;
            evt.resource = "u_cisco_secure_access_destination_list";
            evt.type = "DestinationList";
            evt.metric_name = "u_count";
            evt.severity = 2; 
            evt.description = "Destination list '" + listName + "' reached " + count + " entries (limit 5000)";
            evt.message_key = "Cisco Integration|" + listName + "|DestinationList|u_destination_list|u_count";
            evt.insert();

            gs.info("Event inserted into em_event for '" + listName + "' (" + count + ")");
        }
    }
})();
